{
  "units": [
    {
      "quote_ref": "F000:F012",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Document identification, regulatory headings, dates, and section designations provide taxonomic and structural context without imposing substantive legal obligations, permissions, or prohibitions."
    },
    {
      "quote_ref": "F013",
      "scope_refs": [],
      "kind": "prohibition",
      "meaning": "Except as provided in paragraph (d) of 14 CFR 91.213, no person may take off an aircraft with inoperative instruments or equipment installed unless the conditions specified in paragraph (a) are met."
    },
    {
      "quote_ref": "F014",
      "scope_refs": ["F013"],
      "kind": "condition",
      "meaning": "Except as provided in paragraph (d) of 14 CFR 91.213, taking off an aircraft with inoperative instruments or equipment installed requires that an approved Minimum Equipment List exists for that aircraft."
    },
    {
      "quote_ref": "F015",
      "scope_refs": ["F013"],
      "kind": "condition",
      "meaning": "Except as provided in paragraph (d) of 14 CFR 91.213, taking off an aircraft with inoperative instruments or equipment installed requires that the aircraft has within it a letter of authorization, issued by the responsible Flight Standards office, authorizing operation of the aircraft under the Minimum Equipment List."
    },
    {
      "quote_ref": "F015",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "The letter of authorization authorizing operation of the aircraft under the Minimum Equipment List may be obtained by written request of the airworthiness certificate holder."
    },
    {
      "quote_ref": "F015",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "The Minimum Equipment List and the letter of authorization constitute a supplemental type certificate for the aircraft."
    },
    {
      "quote_ref": "F017",
      "scope_refs": ["F013", "F016"],
      "kind": "requirement",
      "meaning": "Except as provided in paragraph (d) of 14 CFR 91.213, for takeoff with inoperative instruments or equipment installed under paragraph (a), the approved Minimum Equipment List must be prepared in accordance with the limitations specified in paragraph (b) of 14 CFR 91.213."
    },
    {
      "quote_ref": "F018",
      "scope_refs": ["F013", "F016"],
      "kind": "requirement",
      "meaning": "Except as provided in paragraph (d) of 14 CFR 91.213, for takeoff with inoperative instruments or equipment installed under paragraph (a), the approved Minimum Equipment List must provide for the operation of the aircraft with the instruments and equipment in an inoperable condition."
    },
    {
      "quote_ref": "F019",
      "scope_refs": ["F013"],
      "kind": "condition",
      "meaning": "Except as provided in paragraph (d) of 14 CFR 91.213, taking off an aircraft with inoperative instruments or equipment installed requires that the aircraft records available to the pilot include an entry describing the inoperable instruments and equipment."
    },
    {
      "quote_ref": "F020",
      "scope_refs": ["F013"],
      "kind": "condition",
      "meaning": "Except as provided in paragraph (d) of 14 CFR 91.213, taking off an aircraft with inoperative instruments or equipment installed requires that the aircraft is operated under all applicable conditions and limitations contained in the Minimum Equipment List and the letter authorizing the use of the list."
    },
    {
      "quote_ref": "F022",
      "scope_refs": ["F021"],
      "kind": "prohibition",
      "meaning": "Instruments and equipment that are either specifically or otherwise required by the airworthiness requirements under which the aircraft is type certificated, and which are essential for safe operations under all operating conditions, may not be included in a Minimum Equipment List."
    },
    {
      "quote_ref": "F023",
      "scope_refs": ["F021"],
      "kind": "prohibition",
      "meaning": "Instruments and equipment required by an airworthiness directive to be in operable condition may not be included in a Minimum Equipment List unless the airworthiness directive provides otherwise."
    },
    {
      "quote_ref": "F024",
      "scope_refs": ["F021"],
      "kind": "prohibition",
      "meaning": "Instruments and equipment required for specific operations by 14 CFR part 91 may not be included in a Minimum Equipment List."
    },
    {
      "quote_ref": "F025",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "A person authorized to use an approved Minimum Equipment List issued for a specific aircraft under subpart K of 14 CFR part 91, or under part 121, 125, or 135 of chapter I, must use that Minimum Equipment List to comply with the requirements in 14 CFR 91.213."
    }
  ]
}
